body.raw:
{
  "emails": [
    {
      "to": "user1@example.com",
      "subject": "Order Confirmation - Resend Template",
      "templateType": "RESEND",
      "templateId": "order-confirmation",
      "data": {
        "PRODUCT": "Vintage Macintosh",
        "PRICE": 1500,
        "name": "Alice"
      }
    },
    {
      "to": "user2@example.com",
      "subject": "Welcome to Classpicker",
      "templateType": "INTERNAL",
      "template": "<html><body><h1>Welcome {{name}}!</h1><p>Your account has been created successfully.</p></body></html>",
      "data": {
        "name": "Bob"
      }
    },
    {
      "to": "user3@example.com",
      "subject": "Invoice #12345",
      "templateType": "RESEND",
      "templateId": "invoice-template",
      "data": {
        "INVOICE_ID": "12345",
        "AMOUNT": 999,
        "DUE_DATE": "2026-04-15"
      }
    }
  ]
}

{
  "notifications": [
    {
      "type": "WELCOME",
      "channel": "EMAIL",
      "recipient": "newuser@example.com",
      "subject": "Welcome to Our Platform",
      "templateType": "RESEND",
      "templateId": "welcome-template",
      "data": {
        "PLATFORM_NAME": "Classpicker",
        "ACTIVATION_LINK": "https://app.example.com/activate"
      },
      "metadata": {
        "eventId": "evt-welcome-001"
      }
    },
    {
      "type": "RESET_PASSWORD",
      "channel": "EMAIL",
      "recipient": "user@example.com",
      "subject": "Reset Your Password",
      "templateType": "INTERNAL",
      "template": "<html><body><h2>Password Reset Request</h2><p>Click <a href='{{resetLink}}'>here</a> to reset your password</p></body></html>",
      "data": {
        "resetLink": "https://app.example.com/reset?token=abc123"
      },
      "metadata": {
        "eventId": "evt-reset-001"
      }
    },
    {
      "type": "NOTIFICATION",
      "channel": "EMAIL",
      "recipient": "subscriber@example.com",
      "subject": "New Class Available",
      "templateType": "RESEND",
      "templateId": "notification-template",
      "data": {
        "CLASS_NAME": "Python 101",
        "INSTRUCTOR": "John Doe",
        "START_DATE": "2026-04-01"
      },
      "metadata": {
        "eventId": "evt-notification-001"
      }
    }
  ]
}

{
  "emails": [
    {
      "to": "customer1@example.com",
      "subject": "Order Summary",
      "templateType": "RESEND",
      "templateId": "detailed-order",
      "data": {
        "ORDER_ID": "ORD-123456",
        "CUSTOMER_NAME": "John Smith",
        "ITEMS_COUNT": 5,
        "SUBTOTAL": 249.99,
        "TAX": 19.75,
        "SHIPPING": 10,
        "TOTAL": 279.74,
        "DELIVERY_DATE": "2026-03-30",
        "TRACKING_NUMBER": "TRK123456789"
      }
    },
    {
      "to": "customer2@example.com",
      "subject": "Your Bill Payment Confirmation",
      "templateType": "RESEND",
      "templateId": "payment-receipt",
      "data": {
        "PAYMENT_ID": "PAY-987654",
        "AMOUNT": 150.00,
        "PAYMENT_METHOD": "Credit Card",
        "TIMESTAMP": "2026-03-26T02:10:00Z",
        "STATUS": "Completed"
      }
    }
  ]
}

{
  "emails": [
    {
      "to": "admin@example.com",
      "subject": "Daily Report",
      "templateType": "INTERNAL",
      "template": "<h2>Daily Report</h2><p>Total users: {{userCount}}</p><p>New signups: {{newSignups}}</p>",
      "data": {
        "userCount": 1250,
        "newSignups": 15
      }
    },
    {
      "to": "manager@example.com",
      "subject": "Sales Update",
      "templateType": "INTERNAL",
      "template": "<h2>Sales Report - {{month}}</h2><p>Revenue: ${{revenue}}</p><p>Conversion Rate: {{conversionRate}}%</p>",
      "data": {
        "month": "March 2026",
        "revenue": "45000",
        "conversionRate": "3.5"
      }
    }
  ]
}
